arguments.file_text:
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.5rem;
}

.catalog-filters {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.catalog-filters h3 {
    margin: 0 0 0.25rem 0;
    font-size: 1.1rem;
}

.catalog-filters fieldset {
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 0.75rem;
    margin: 0;
}

.catalog-filters legend {
    font-weight: 600;
    font-size: 0.9rem;
    padding: 0 0.4rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    font-size: 0.85rem;
    font-weight: 500;
}

.price-inputs input {
    padding: 0.4rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.btn-apply {
    padding: 0.6rem;
    border: none;
    border-radius: 6px;
    background: #0066cc;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
}

.btn-apply:hover {
    background: #0052a3;
}

.btn-clear {
    padding: 0.6rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    background: #fff;
    color: #333;
    font-weight: 500;
    cursor: pointer;
}

.btn-clear:hover {
    background: #f5f5f5;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    padding: 0.75rem 0;
    border-bottom: 1px solid #e0e0e0;
    margin-bottom: 1rem;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control label {
    font-weight: 500;
    font-size: 0.9rem;
    white-space: nowrap;
}

.sort-control select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
    background: #fff;
}

.results-summary {
    font-size: 0.9rem;
    color: #666;
}

@{
    var totalPages = (int)Math.Ceiling((double)TotalCount / PageSize);
}

@if (totalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="page-btn"
                disabled="@(Page <= 1)"
                @onclick="() => GoToPage(Page - 1)">
            Previous
        </button>

        @foreach (var p in GetPageNumbers(totalPages))
        {
            @if (p == -1)
            {
                <span class="page-ellipsis">…</span>
            }
            else
            {
                <button class="page-btn @(p == Page ? "active" : "")"
                        @onclick="() => GoToPage(p)">
                    @p
                </button>
            }
        }

        <button class="page-btn"
                disabled="@(Page >= totalPages)"
                @onclick="() => GoToPage(Page + 1)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }

    /// <summary>
    /// Returns page numbers to display, using -1 as a sentinel for ellipsis.
    /// Shows first, last, and a window around the current page.
    /// </summary>
    private List<int> GetPageNumbers(int totalPages)
    {
        var pages = new List<int>();
        if (totalPages <= 7)
        {
            for (int i = 1; i <= totalPages; i++) pages.Add(i);
            return pages;
        }

        pages.Add(1);

        if (Page > 3) pages.Add(-1);

        for (int i = Math.Max(2, Page - 1); i <= Math.Min(totalPages - 1, Page + 1); i++)
            pages.Add(i);

        if (Page < totalPages - 2) pages.Add(-1);

        pages.Add(totalPages);

        return pages;
    }
}

