    display: flex;
    gap: 2rem;
    align-items: flex-start;
}

.catalog-sidebar {
    flex: 0 0 25%;
    min-width: 220px;
    position: sticky;
    top: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-status {
